$root='C:\Users\18432\Desktop\元DGTF-多模并行架构'; $t=Join-Path $root '.dsh_gate_tmp'
try { New-Item -ItemType Directory -Force -Path (Join-Path $t 'a\b') -ErrorAction Stop | Out-Null; 'mkdir OK' } catch { 'mkdir FAIL: ' + $_.Exception.Message }
try { Set-Content -LiteralPath (Join-Path $t 'a\b\f.txt') -Value 'x' -ErrorAction Stop; 'write OK' } catch { 'write FAIL: ' + $_.Exception.Message }
try { New-Item -ItemType Directory -Force -Path (Join-Path $env:USERPROFILE 'AppData\Local\Temp\dshacl_probe\x') -ErrorAction Stop | Out-Null; 'temp-mkdir OK' } catch { 'temp-mkdir FAIL: ' + $_.Exception.Message }
$acl = Get-Acl -LiteralPath $t; 'Owner=' + $acl.Owner; $acl.Access | ForEach-Object { "$($_.IdentityReference) $($_.AccessControlType) $($_.FileSystemRights)" }

$root='C:\Users\18432\Desktop\元DGTF-多模并行架构'; $base=Join-Path $root '.probe_mode'; New-Item -ItemType Directory -Force -Path $base | Out-Null
foreach ($m in @('700','777')) { $p = Join-Path $base ("m"+$m); python -c "import os,sys; os.mkdir(sys.argv[1], int(sys.argv[2],8))" $p $m 2>&1 | Out-Null }
$p=Join-Path $base 'm000'; python -c "import os,sys; os.mkdir(sys.argv[1])" $p 2>&1 | Out-Null
foreach ($p in (Get-ChildItem -LiteralPath $base -Directory)) { try { $a=(Get-Acl -LiteralPath $p.FullName).Access | ForEach-Object { "$($_.IdentityReference)|$($_.AccessControlType)|$($_.FileSystemRights)" }; "$($p.Name): " + ($a -join ' ; ') } catch { "$($p.Name): ACL-READ-DENIED" } }
python -c "import sys,tempfile; print(tempfile.gettempdir())"

$root='C:\Users\18432\Desktop\元DGTF-多模并行架构'
cmd /c rd /s /q "$root\.probe_mode" 2>&1; "rd probe_mode exit=$LASTEXITCODE"
cmd /c rd /s /q "$root\.dsh_gate_tmp" 2>&1; "rd gate_tmp exit=$LASTEXITCODE"
if (Test-Path -LiteralPath "$root\.probe_mode") { 'probe_mode still exists' } else { 'probe_mode gone' }
if (Test-Path -LiteralPath "$root\.dsh_gate_tmp") { 'gate_tmp still exists'; Get-ChildItem -LiteralPath "$root\.dsh_gate_tmp" -Force | Select-Object -ExpandProperty Name } else { 'gate_tmp gone' }
